  } else { l.push(t.ag_inc_sin_movimiento); }
  return { json: { chat_id: a.telegram_id, text: l.join('\n'), btn: t.ag_btn_recibido, cb: 'ag_ack_' + inc.id, inc_id: inc.id } };
